import React, { useEffect, useState } from 'react';
import axios from 'axios';

export default function ScenarioList() {
  const [scenarios, setScenarios] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:5000/api/scenarios').then(res => setScenarios(res.data));
  }, []);

  const generateVideo = (id) => {
    window.open(`/api/generate/${id}`, '_blank');
  };

  return (
    <div>
      {scenarios.map(s => (
        <div key={s.id} style={{marginBottom:'20px', border:'1px solid #ccc', padding:'10px'}}>
          <h3>{s.title}</h3>
          <button onClick={()=>generateVideo(s.id)}>Generate Video</button>
        </div>
      ))}
    </div>
  );
}
